await (async(page)=>{const errors=[];page.on('pageerror',e=>errors.push(String(e)));await page.goto('http://localhost:8792');await page.emulateMedia({reducedMotion:'no-preference'});await page.setViewportSize({width:1440,height:950});await page.getByRole('button',{name:'Search Trials',exact:false}).click();await page.getByText(/\d+ trials found/).waitFor({timeout:60000});const ids=await page.getByRole('link',{name:'View Trial',exact:true}).evaluateAll(es=>es.map(e=>e.href.match(/NCT\d{8}/)[0]));return{url:page.url(),title:await page.title(),errors,count:ids.length,hasBB102:ids.includes('NCT06258408'),terminatedAbsent:!ids.includes('NCT02767934'),completedAbsent:!ids.includes('NCT05034497'),overflow:await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth)};})(page);
